def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 3:
                rich_opp += 1
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    danger = 0.0
    if no_water_days >= 2:
        danger += 0.7
    elif no_water_days == 1:
        danger += 0.35
    if hp <= 2:
        danger += 0.7
    elif hp <= 4:
        danger += 0.35

    if danger >= 1.0:
        bid = max(highest_prev + 2.0, DAILY_SALARY * 1.05)
        return float(min(budget, bid))

    if supply >= 23:
        base = DAILY_SALARY * 0.28
    elif supply >= 20:
        base = DAILY_SALARY * 0.42
    elif supply >= 17:
        base = DAILY_SALARY * 0.62
    else:
        base = DAILY_SALARY * 0.88

    reactive = 0.0
    if highest_prev > 0:
        if highest_prev >= DAILY_SALARY * 1.8:
            reactive = DAILY_SALARY * 0.08
        elif highest_prev >= DAILY_SALARY * 1.2:
            reactive = DAILY_SALARY * 0.18
        elif highest_prev >= DAILY_SALARY * 0.8:
            reactive = DAILY_SALARY * 0.28
        else:
            reactive = max(0.0, highest_prev - base) * 0.35

    opp_factor = rich_opp * 2.5 + urgent_opp * 2.0
    bid = base + reactive + (supply_pressure * 10.0) + opp_factor + (danger * 18.0)

    if avg_prev > 0 and supply <= 17:
        bid = max(bid, avg_prev * 0.78)

    if hp >= 8 and no_water_days == 0 and supply >= 21:
        bid *= 0.82

    reserve_floor = DAILY_SALARY * 1.2 if hp > 4 else DAILY_SALARY * 0.4
    max_affordable = budget - reserve_floor
    if max_affordable < DAILY_SALARY * 0.2:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_players = len(alive_opponents) + 1 # Including myself

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    remaining_days = EPISODE_DAYS - day_context['day']

    bid_value = float(DAILY_SALARY)

    # 1. Supply Scarcity Adjustment
    total_demand = num_alive_players * WATER_REQ
    current_supply = day_context['supply']

    if current_supply < total_demand:
        scarcity_factor = total_demand / current_supply
        bid_value *= (1 + (scarcity_factor - 1) * 0.2)
    else:
        ample_factor = current_supply / total_demand
        bid_value *= (1 - (ample_factor - 1) * 0.1)

    bid_value = max(bid_value, DAILY_SALARY * 0.6)

    # 2. My HP Adjustment
    if my_status['hp'] <= 3:
        bid_value *= 1.25
    elif my_status['hp'] <= 6:
        bid_value *= 1.1

    # 3. Budget Management Adjustment
    if remaining_days > 0:
        my_avg_daily_budget = my_status['budget'] / remaining_days
        if my_avg_daily_budget < DAILY_SALARY * 0.75:
            bid_value *= 0.8
        elif my_avg_daily_budget > DAILY_SALARY * 1.5:
            bid_value *= 1.1

    # 4. Opponent Reaction (based on yesterday's bids)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid > DAILY_SALARY * 1.0:
            bid_value = max(bid_value, highest_prev_bid * 1.05)
        elif highest_prev_bid < DAILY_SALARY * 0.8:
            bid_value = max(bid_value, highest_prev_bid * 1.1)

    # 5. Last day desperation
    if day_context['day'] == EPISODE_DAYS - 1 and my_status['hp'] < 10:
        bid_value = my_status['budget'] * 0.95

    final_bid = max(1.0, min(my_status['budget'], bid_value))

    return float(final_bid)
